WITH with_windows AS (SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY city, segment), 4) AS credit_limit_share, SUM(age) OVER (PARTITION BY country ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_age, ROW_NUMBER() OVER (PARTITION BY city ORDER BY signup_date, id) AS event_seq FROM customers) SELECT CASE WHEN running_age >= 251 THEN 'HIGH' ELSE 'LOW' END AS running_age_tier, CASE WHEN credit_limit_share >= 0.85 THEN 'HIGH' ELSE 'LOW' END AS credit_limit_share_tier, STDDEV_SAMP(age) AS age_stddev, COUNT(*) FILTER (WHERE country = 'SG') AS sg_rows, GROUPING(CASE WHEN running_age >= 251 THEN 'HIGH' ELSE 'LOW' END) AS grouping_id FROM with_windows GROUP BY ROLLUP (CASE WHEN running_age >= 251 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN credit_limit_share >= 0.85 THEN 'HIGH' ELSE 'LOW' END);
